@implements IAsyncDisposable
@inject IJSRuntime JS

<div @ref="_container">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }
    [Parameter] public int TimeoutSeconds { get; set; } = 300;
    [Parameter] public EventCallback OnIdle { get; set; }
    [Parameter] public EventCallback OnActive { get; set; }

    private ElementReference _container;
    private IJSObjectReference? _module;
    private DotNetObjectReference<UserActivityTracker>? _dotNetRef;

    private bool _isIdle;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/UserActivityTracker.razor.js");
            await _module.InvokeVoidAsync("initialize", _container, _dotNetRef, TimeoutSeconds * 1000);
        }
    }

    [JSInvokable]
    public async Task OnUserIdle()
    {
        if (!_isIdle)
        {
            _isIdle = true;
            await OnIdle.InvokeAsync();
        }
    }

    [JSInvokable]
    public async Task OnUserActive()
    {
        if (_isIdle)
        {
            _isIdle = false;
            await OnActive.InvokeAsync();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            try
            {
                await _module.InvokeVoidAsync("dispose");
                await _module.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
        }
        _dotNetRef?.Dispose();
    }
}

let timer = null;
let dotNetHelper = null;
let timeoutMs = 300000;
let events = ['mousemove', 'keydown', 'click', 'scroll'];
let boundHandler = null;

function resetTimer() {
    clearTimeout(timer);
    timer = setTimeout(async () => {
        await dotNetHelper.invokeMethodAsync('OnUserIdle');
    }, timeoutMs);
}

function handleActivity() {
    dotNetHelper.invokeMethodAsync('OnUserActive');
    resetTimer();
}

export function initialize(container, helper, timeout) {
    dotNetHelper = helper;
    timeoutMs = timeout;
    boundHandler = handleActivity;

    events.forEach(event => document.addEventListener(event, boundHandler, { passive: true }));
    resetTimer();
}

export function dispose() {
    clearTimeout(timer);
    timer = null;
    if (boundHandler) {
        events.forEach(event => document.removeEventListener(event, boundHandler));
        boundHandler = null;
    }
    dotNetHelper = null;
}

